fn v3_fall_back_to_passive(&mut self, version, rnd, player, data, debug) {
  // handler.rs:417
  if version < 2 { return; }

  // handler.rs:421 — game = data.cache.game (dyn AbstractGame)
  //   vtable+0x40 = get_game_mode() -> (tag, ptr)
  //   tag: 0=Moba(&MobaMode) 1=SingleLane(&SingleLaneMode) 2=DeathMatch(&DeathMatchMode)
  if game.get_game_mode().tag == 2 /*DeathMatch*/ { return; }

  // handler.rs:424~428 — 대체 플랜 만들기 (get_game_mode 를 다시 호출)
  let plan: BigPlan = if game.get_game_mode().tag == 1 /*SingleLane*/ {
      // handler.rs:425 — 인라인 리터럴, 아무 계산도 안 함
      BigPlan::SinglePlanLine(SinglePlanLine {
          chats: Vec::new(),      // cap=0, ptr=dangling(8), len=0
          in_recall: false,       // +0x20 = 0
          line: LineType::Mid,    // +0x21 = 1  ← 모드의 실제 라인을 읽지 않음
      })                          // BigPlan 판별자 = 4
  } else {
      // handler.rs:427 — passive_plan(self, version, rnd, player, data, debug)
      //   반환 타입은 (BigPlan, u8) 392B 이지만 앞 384B(BigPlan)만 memcpy 하고
      //   두 번째 u8(사유코드)은 버린다
      self.passive_plan(version, rnd, player, data, debug).0
  };

  // handler.rs:429 — rule_scope::plan_allowed(data.context, &plan)  [전부 인라인됨]
  //   plan_allowed(rule_scope.rs:100-101) = goal_allowed(ctx, plan.goal())
  //   goal = BigPlan::goal(&plan) -> BigGoal (24B, tag@+0)
  //   t = ctx.tutorial (GameContext+0x38, TutorialType 0..8)
  //     0=None 1=First 2=TopSolo 3=Bottom 4=MidSolo 5=MidBottom 6=JungleOnly 7=Line 8=Total
  let allowed = match goal.tag {
      // rule_scope.rs:92 line_exists(ctx, line) → runner.rs:274 tutorial.spawn_line_minion(line)
      0 /*Line(line@+0x1)*/ => match line {
          0 /*Top*/    => matches!(t, 0|2|7|8),        // runner.rs:283 spawn_top_minion
          1 /*Mid*/    => matches!(t, 0|4|5|7|8),      // runner.rs:287 spawn_mid_minion
          2 /*Bottom*/ => matches!(t, 0|1|3|5|7|8),    // runner.rs:291 spawn_bottom_minion
      },
      // rule_scope.rs:95 → runner.rs:294 tutorial.player_count() <비교식 상수접힘>
      1 /*Jungle*/ => matches!(t, 0|6|8),              // camp/team 페이로드는 읽지 않음
      // rule_scope.rs:93 morgard_exists(ctx) → runner.rs:262 tutorial.spawn_epic()
      2 /*Epic*/   => matches!(t, 0|7|8),
      // rule_scope.rs:94 serpen_exists(ctx) → runner.rs:266 tutorial.spawn_serpen()
      3 /*Serpen*/ => matches!(t, 0|5|7|8),
      // 나머지는 무조건 허용 (IR 상 switch case 4,5,6 이 곧장 allowed 블록 %61 로)
      4 /*Nexus*/ | 5 /*Battle*/ | 6 /*Recall*/ => true,
  };

  if !allowed {
      drop(plan);   // 만든 플랜을 버리고 아무 변경 없이 종료
      return;
  }

  // ---- 여기부터가 실제 적용 ----
  // handler.rs:432 — mf_note_swap(self, 29, game.tick())  [handler.rs:409 인라인]
  self.mf_swap = (29u8, game.tick());               // +0x1610 / +0x1618
  // handler.rs:433
  self.v3_lapse_passive_fallbacks += 1;             // +0x1628
  // handler.rs:434 — 기존 self.plan 을 drop 하고 새 플랜으로 교체
  //   (IR: 새 플랜을 임시 %9 로 복사 → drop_glue(self.plan) → memcpy self.plan <- %9,
  //    drop 이 unwind 해도 self.plan 이 유효하도록 cleanuppad 에서도 memcpy 를 수행)
  self.plan = plan;                                 // +0x5e8
  // handler.rs:435 — 새 플랜에서 서브플랜을 산출
  let sp = BigPlan::sub_plan(&mut self.plan, version, rnd, player, data,
                             &self.data /*+0x0, 248B*/,
                             &mut self.team_plan /*+0xf8*/,
                             &self.positioning_score /*+0x990*/,
                             debug);
  // handler.rs:436
  SubPlan::merge(&mut self.sub_plan /*+0x768*/, &sp);
  // handler.rs:437 return
}
